#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: HUM-001 owner-controlled public identity and custody approval.
# --------------------------------------------------------------------------

TOTAL_STAGES=5
ENV_FILE="${HUM001_ENV_FILE:-contracts/.env}"

is_address() {
  [[ "$1" =~ ^0x[0-9a-fA-F]{40}$ ]] && [[ ! "$1" =~ ^0x0{40}$ ]]
}

ask_address() {
  local key="$1" prompt="$2" value
  while true; do
    ask "$key" "$prompt"
    printf -v value '%s' "${!key}"
    if is_address "$value"; then return 0; fi
    warn "Enter a nonzero Ethereum public address: 0x followed by 40 hexadecimal characters."
  done
}

same_address() { [[ "${1,,}" == "${2,,}" ]]; }

require_distinct() {
  local left_name="$1" left="$2" right_name="$3" right="$4"
  if same_address "$left" "$right"; then
    warn "$left_name and $right_name must use distinct wallets for HUM-001."
    return 1
  fi
}

banner "Nebula HUM-001 identity and custody approval"

stage "Safety and custody model"
say "This wizard records PUBLIC Arbitrum Sepolia addresses only."
warn "Never enter a seed phrase, private key, keystore password, RPC credential, or wallet recovery data."
step "Keep the deployer in an owner-controlled encrypted Foundry keystore or hardware wallet."
step "Keep the contract owner in an owner-controlled wallet; never in the backend environment."
step "Keep the backend verifier key only in an ignored backend secret file or secret manager."
step "Keep AI-user and provider keys only in their browser wallets."
step "Keep the worker signer key only in an ignored worker secret file; it needs no funds."
confirm "Do you accept this custody model and confirm you will enter public addresses only?" || {
  warn "Custody model not approved; nothing was written."
  exit 1
}

stage "Deployer and contract owner"
ask_address HUM001_DEPLOYER_ADDRESS "Paste the deployer PUBLIC address:"
if confirm "For this testnet rehearsal, intentionally use the deployer as contract owner too?"; then
  HUM001_DEPLOYER_OWNER_SHARED=true
  NEBULA_CONTRACT_OWNER="$HUM001_DEPLOYER_ADDRESS"
  say "Shared deployer/owner custody has been explicitly recorded for testnet only."
else
  HUM001_DEPLOYER_OWNER_SHARED=false
  ask_address NEBULA_CONTRACT_OWNER "Paste the contract-owner PUBLIC address:"
  require_distinct "deployer" "$HUM001_DEPLOYER_ADDRESS" "contract owner" "$NEBULA_CONTRACT_OWNER" || exit 1
fi

stage "Backend verifier"
ask_address NEBULA_BACKEND_VERIFIER "Paste the backend-verifier PUBLIC address:"
require_distinct "backend verifier" "$NEBULA_BACKEND_VERIFIER" "deployer" "$HUM001_DEPLOYER_ADDRESS" || exit 1
require_distinct "backend verifier" "$NEBULA_BACKEND_VERIFIER" "contract owner" "$NEBULA_CONTRACT_OWNER" || exit 1
say "This address will assign providers, submit proofs, and settle jobs. Its secret is not collected here."

stage "AI user, provider, and worker signer"
ask_address HUM001_AI_USER_ADDRESS "Paste the AI-user PUBLIC address:"
ask_address HUM001_PROVIDER_ADDRESS "Paste the provider-payout PUBLIC address:"
ask_address HUM001_WORKER_SIGNER_ADDRESS "Paste the worker-signer PUBLIC address:"
roles=(
  "deployer:$HUM001_DEPLOYER_ADDRESS"
  "owner:$NEBULA_CONTRACT_OWNER"
  "verifier:$NEBULA_BACKEND_VERIFIER"
  "AI user:$HUM001_AI_USER_ADDRESS"
  "provider:$HUM001_PROVIDER_ADDRESS"
  "worker signer:$HUM001_WORKER_SIGNER_ADDRESS"
)
for ((i=0; i<${#roles[@]}; i++)); do
  for ((j=i+1; j<${#roles[@]}; j++)); do
    left_name="${roles[i]%%:*}"; left="${roles[i]#*:}"
    right_name="${roles[j]%%:*}"; right="${roles[j]#*:}"
    if [[ "$HUM001_DEPLOYER_OWNER_SHARED" == true && "$left_name" == deployer && "$right_name" == owner ]]; then
      continue
    fi
    require_distinct "$left_name" "$left" "$right_name" "$right" || exit 1
  done
done

stage "Review, approve, and save"
say "Public identity map:"
say "Deployer:         $HUM001_DEPLOYER_ADDRESS"
say "Contract owner:   $NEBULA_CONTRACT_OWNER"
say "Backend verifier: $NEBULA_BACKEND_VERIFIER"
say "AI user:          $HUM001_AI_USER_ADDRESS"
say "Provider payout:  $HUM001_PROVIDER_ADDRESS"
say "Worker signer:    $HUM001_WORKER_SIGNER_ADDRESS"
say "Deployer/owner shared: $HUM001_DEPLOYER_OWNER_SHARED"
confirm "Approve this exact public identity map for HUM-001?" || {
  warn "Identity map not approved; nothing was written."
  exit 1
}
if ! git check-ignore -q "$ENV_FILE"; then
  warn "$ENV_FILE is not protected by a Git ignore rule. Nothing was written."
  exit 1
fi
write_env HUM001_DEPLOYER_ADDRESS "$HUM001_DEPLOYER_ADDRESS"
write_env HUM001_DEPLOYER_OWNER_SHARED "$HUM001_DEPLOYER_OWNER_SHARED"
write_env NEBULA_CONTRACT_OWNER "$NEBULA_CONTRACT_OWNER"
write_env NEBULA_BACKEND_VERIFIER "$NEBULA_BACKEND_VERIFIER"
write_env HUM001_AI_USER_ADDRESS "$HUM001_AI_USER_ADDRESS"
write_env HUM001_PROVIDER_ADDRESS "$HUM001_PROVIDER_ADDRESS"
write_env HUM001_WORKER_SIGNER_ADDRESS "$HUM001_WORKER_SIGNER_ADDRESS"
write_env HUM001_OWNER_APPROVED true
chmod 600 "$ENV_FILE"
say "Saved public values to $ENV_FILE with mode 600. No secret was requested or stored."
finish
